function OnUpdate(so_actor, time_key, length)
{
	local t = time_key / length;
	local c = 0.25 + 0.75 * (1-sin(t * PI));
	Actor_SetModelGlowColor(so_actor, c,c,c,1);
}

function OnUpdate(so_actor, time_key, length)
{
	local t = time_key / length;
	local c = m_randf(0,1);// 0.25 + 0.75 * (1-sin(t * PI));
	Actor_SetModelGlowColor(so_actor, c,c,c,1);
}

function OnUpdate(so_actor, time_key, length)
{
	local c = 0;
	Actor_SetModelGlowColor(so_actor, c,c,c,1);
}

function OnUpdate(so_actor, time_key, length)
{
	local t = time_key / length;
	local c = 0.95 * (1-sin(PI/2+t * 2 * PI));
	Actor_SetModelGlowColor(so_actor, c,c,c,1);
}

node.interaction_1_script_to_run_on_interacti:
function UpdateSpawnEntranceReference(so_self)
{
	local pos = StageObject_GetStagePosition(so_self);
	local at = "actors/objects/shelter-entry-hatch.xml";
	local spawn_entrance = Stage_QueryNearestActorWithType(pos[0], pos[1], pos[2], 2*20*60, at);
	if (spawn_entrance == null)
		return;
	StageObject_SetKeyValueStageObjectReference(so_self, "spawn_entrance", spawn_entrance);
}

function OnInteraction(so_self, so_activator)
{
	UpdateSpawnEntranceReference(so_self);

	local tutorial_quest_id = "quests/shelter-defence.nut";
	local is_quest_handled = Game_IsQuestCurrent(tutorial_quest_id) || Game_IsQuestCompleted(tutorial_quest_id);

	if (!StageObject_GetKeyValue(so_self, "extracted_cpu", false))
	{
		Actor_SetInteractionEnabled(so_self, "investigate", !is_quest_handled);
		Actor_SetInteractionEnabled(so_self, "activate", false);
		return;
	}

	if (is_quest_handled)
	{
		Actor_SetInteractionEnabled(so_self, "investigate", false);

		local kvs = StageObject_GetKeyValueStore(so_self);
		local so_entrance = KeyValueStore_GetKeyValue(kvs, "spawn_entrance");
		if (so_entrance == null)
			return;

		if (StageObject_GetKeyValue(so_entrance, "cleared"))
		{
			Actor_SetInteractionEnabled(so_self, "activate", false);
			Actor_SetInteractionEnabled(so_self, "after_completed", true);
		}
		else
		{
			Actor_SetInteractionEnabled(so_self, "activate", true);
		}
	}
	else
	{
		Actor_SetInteractionEnabled(so_self, "investigate", true);
		Actor_SetInteractionEnabled(so_self, "activate", false);
		return;
	}
}

node.interaction_2_script_to_run_on_interacti:
function GetWaveKeyValue(kvs, wave, id)
{
	return KeyValueStore_GetKeyValue(kvs, "wave_" + wave.tostring() + "_" + id);
}

function SpawnEnemy(kvs, wave, so_entrance, so_target, angle_offset, path_key)
{
	local at = GetWaveKeyValue(kvs, wave, "actor_type");
	local pos = StageObject_GetPosition(so_entrance);
	local angle = StageObject_GetAngle(so_entrance) + angle_offset;
	Actor_SetActorFlag(so_entrance, "SOLID", false);

	local radius = 74;
	local angle_radians = angle/180*PI;
	local offset_x = radius * cos(angle_radians);
	local offset_y = radius * sin(angle_radians);

	local so = Stage_CreateActor(at, pos[0] + offset_x, pos[1] + offset_y, 0, false);

	if (so == null)
		return;

	StageObject_SetGlobal(so, false);
	StageObject_SetScale(so, 0.9 + 0.1 * m_randf());

	StageObject_SetAngle(so, angle);
	StageObject_SetVisible(so, false);
	Actor_SetActorFlag(so, "SOLID", false);

	Actor_QueueActionWait(so, 0.9 * m_randf());

	local playback_speed = 0.5 + 1.0 * m_randf();
	local script = @"
		StageObject_SetVisible($so, true);
		Actor_SetActorFlag($so, ""SOLID"", true);
	";
	script = string_replace(script, "$so", so.tostring());
	Actor_QueueActionRunScript(so, script);

	Actor_QueueActionPlayAnimationWithParameters(so, "climb_up", playback_speed, 0, true);

	Game_StartHordeAttack(so, so_target, kvs, path_key);
	return so;
}

function GetNumberOfPaths(so_self)
{
	local kvs = StageObject_GetKeyValueStore(so_self);
	local num = 0;

	for (local i = 0; i < 4; i++)
	{
		local path = KeyValueStore_GetKeyValue(kvs, "walk_path_" + i);
		if (path == null)
			break;
		num++;
	}
	return num;
}

function GetNumberOfWaves(so_self)
{
	local kvs = StageObject_GetKeyValueStore(so_self);
	local num = 0;

	for (local i = 0; i < 4; i++)
	{
		local path = KeyValueStore_GetKeyValue(kvs, "wave_" + i + "_actor_type");
		if (path == null)
			break;
		num++;
	}
	return num;
}

function AllMonstersKilled(so_self)
{
	local kvs = StageObject_GetKeyValueStore(so_self);
	local num_waves_done = KeyValueStore_GetKeyValue(kvs, "num_waves_done");
	local at = GetWaveKeyValue(kvs, num_waves_done, "actor_type");
	if (at == null)
		at = "actors/enemies/ex-human-underground-horde.xml";
	local pos = StageObject_GetPosition(so_self);
	local enemies = Stage_QueryActorsWithTypeInRadius(pos[0], pos[1], pos[2], 2 * 20 * 60, at);

	if (enemies.len() > 0)
	{
		return false;
	}

	return true;
}

function CheckCompletion(so_self)
{
	if (!AllMonstersKilled(so_self))
		return;

	local quest_id = "quests/shelter-defence.nut";//StageObject_GetKeyValue(so_self, "quest_id");
	Game_SendQuestPhaseGoalCommandWord(quest_id, "PHASE_0", "KILL_MONSTERS", "complete");

	local kvs = StageObject_GetKeyValueStore(so_self);
	local so_entrance = KeyValueStore_GetKeyValue(kvs, "spawn_entrance");
	StageObject_SetKeyValueBoolean(so_entrance, "cleared", true);

	Game_SetStagePointOfInterestCompleted(so_self);
	Game_RemoveAllBlockingPaths();
}

function VisualizePath(so_self)
{
	local kvs = StageObject_GetKeyValueStore(so_self);
	local effect = "effects/shelter-horde-trail-visualization.xml";
	for (local i = 0; i < 4; i++)
	{
		local kv_path = KeyValueStore_GetKeyValue(kvs, "walk_path_" + i);
		if (kv_path == null)
			return;
		Game_VisualizePathKeyValue(kv_path, so_self, effect, 5, 5, -10, false);
	}
}

function OnInteraction(so_self, so_activator)
{
	local kvs = StageObject_GetKeyValueStore(so_self);

	local num_waves_done = KeyValueStore_GetKeyValue(kvs, "num_waves_done");
	local num_waves = GetNumberOfWaves(so_self);

	//Engine_Warning("wave " + (num_waves_done + 1) + " of " + num_waves);

	if (num_waves_done >= num_waves)
	{
		Actor_SetInteractionTriggerParameterFloat(so_self, "spawn_check", 0.5);
		Actor_SetInteractionEnabled(so_self, "spawn_check", false);
		Actor_SetInteractionEnabled(so_self, "activate", false);
		Actor_StopAnimationWithFade(so_self, "activate_start", 2);

		local so_entrance = KeyValueStore_GetKeyValue(kvs, "spawn_entrance");
		Actor_StopAnimationWithFade(so_entrance, "spawning_monsters", 2);
		CheckCompletion(so_self);
		return;
	}

	local num_bursts = GetWaveKeyValue(kvs, num_waves_done, "num_bursts");
	local num_bursts_done = KeyValueStore_GetKeyValue(kvs, "num_bursts_done");

	//Engine_Warning("burst " + (num_bursts_done) + " of " + num_bursts);

	if (num_bursts_done >= num_bursts)
	{
		Actor_SetInteractionTriggerParameterFloat(so_self, "spawn_check", 0.5);
		if (!AllMonstersKilled(so_self))
			return;

		num_waves_done++;
		KeyValueStore_SetKeyValueInteger(kvs, "num_waves_done", num_waves_done);
		KeyValueStore_SetKeyValueInteger(kvs, "num_bursts_done", 0);

		if (num_waves_done < num_waves)
		{
			VisualizePath(so_self);
			local text_major = LOC_TEXT("Monsters incoming!");
			local waves_remaining = num_waves - num_waves_done;
			local text_minor = LOC_TEXT("Wave [NUMBER]");
			text_minor = string_replace(text_minor, "[NUMBER]", (num_waves_done+1).tostring() + " / " + num_waves);
			Game_AddMajorNotification("ui/gfx/icon-quest.png", "sfx/quest-new", text_major, text_minor, "TOP");
		}
		else
		{
			local text_major = LOC_TEXT("Victory!");
			local text_minor = LOC_TEXT("The shelter is now ready to be entered.");
			Game_AddMajorNotification("ui/gfx/icon-quest.png", "sfx/quest-new", text_major, text_minor, "TOP");
		}

		return;
	}

	local burst_interval = GetWaveKeyValue(kvs, num_waves_done, "burst_interval");
	Actor_SetInteractionTriggerParameterFloat(so_self, "spawn_check", burst_interval);

	num_bursts_done++;
	KeyValueStore_SetKeyValueInteger(kvs, "num_bursts_done", num_bursts_done);

	local so_entrance = KeyValueStore_GetKeyValue(kvs, "spawn_entrance");
	local num_paths = GetNumberOfPaths(so_self);

	local num_per_burst = GetWaveKeyValue(kvs, num_waves_done, "num_per_burst");

	local angle_spread = 180;
	local angle_step;
	local angle_start = 0;

	if (num_per_burst > 1)
	{
		angle_step = angle_spread / (num_per_burst-1);
		angle_start = 0;
	}
	else
	{
		angle_step = 0;
		angle_start = angle_spread/2;
	}

	local num_spawned = 0;


	for (local i = 0; i < num_per_burst; i++)
	{
		local angle = angle_start + i * angle_step;
		local path = "walk_path_" + (num_spawned%num_paths).tostring();
		SpawnEnemy(kvs, num_waves_done, so_entrance, so_self, angle, path);
		num_spawned++;
	}
}

node.interaction_3_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_SetCinemaMode(true);
	local pos = StageObject_GetPosition(so_self);
	Game_SetRespawnPoint(pos[0] + 90, pos[1], pos[2]);
	Actor_PlayAnimation(so_self, "undo_wave");
	Actor_StopAnimationWithFade(so_self, "active", 0);

	local t = Game_GetWorldTimeRelativeDayBetween0And1AfterMidnight();
	Game_SetOverrideTimeOfDayValueAnimation(t, t-1, 15);
	Game_SetOverrideTimeOfDayEnabled(true);

	local so_camera = StageObject_GetById("cinema_camera");
	Stage_SetActiveCamera(so_camera);
	local kvs_camera_paths = ActorType_GetKeyValueStore(Actor_GetActorType(so_self));
	Camera_RemoveAllAnimationsFromQueue(so_camera);
	Camera_AddAnimationToQueueAllPaths(so_camera, kvs_camera_paths, so_self);
	//Camera_SetStageCameraAfterAnimationQueueIsFinished(so_camera, Stage_GetBaseCamera());
	//Camera_SetStageCameraAnimationQueueLooping(so_camera, true);
	NX_SwitchMusic("music/Campfire", 0.5, 1);

	local quest_id = StageObject_GetKeyValue(so_self, "quest_id");
	if (quest_id != null && quest_id != "")
		Game_SetQuestFailed(quest_id);
}

