node.interaction_5_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	Game_LogEvent("SHELTER_DEFENCE", "WON");

	Game_AddActorNotification(so_activator, LOC_TEXT("I think it's safe to enter that shelter now."));

	// Fix for legacy saves
	if (!Game_IsRecipeUnlocked("TURRET_AMMO_EXPANSION_1"))
	{
		Game_SetBuildableUnlocked("actors/buildables/turret-machine-gun.xml", true, true);
		Game_SetRecipeUnlocked("TURRET_AMMO_EXPANSION_1", true, true);
	}
}

node.interaction_6_script_to_run_on_interacti:
function OnInteraction(so_self, so_activator)
{
	local num = Game_GetWorldStateAsInteger("SHELTER_DEFENCE", "extracted_cpus", 0);
	num++;
	Game_SetWorldState("SHELTER_DEFENCE", "extracted_cpus", num.tostring());
	StageObject_SetKeyValueBoolean(so_self, "extracted_cpu", true);
	local text;
	if (num == 1)
	{
		text = LOC_TEXT("I can now override this shelter security system to attract the monsters out of the [ORANGE]shelter[WHITE] nearby.");
		Game_AddActorNotificationWithDelay(so_activator, text, 0.4);
		text = LOC_TEXT("I should find more of these [MATERIAL_ICON=CPU].");
		Game_AddActorNotificationWithDelay(so_activator, text, 0);
	}
	else
	{
		text = LOC_TEXT("Overridden and [MATERIAL_ICON=CPU] extracted. [EMOJI=flexed biceps]");
		Game_AddActorNotificationWithDelay(so_activator, text, 0.4);
	}

	Actor_PlayAnimation(so_self, "extract_cpu");
	Game_SpawnMaterials(so_self, so_activator, "1xCPU");
	Actor_InteractWithInteraction(so_self, so_self, "init");
}
